using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Models;

public class PaginatedListTests
{
    [Fact]
    public void Create_ReturnsCorrectPage()
    {
        // Arrange
        var context = TestDbContextFactory.CreateWithData();
        var students = context.Students.OrderBy(s => s.LastName);

        // Act
        var page = PaginatedList<Student>.Create(students, 1, 2);

        // Assert
        Assert.Equal(2, page.Count);
        Assert.Equal(1, page.PageIndex);
        Assert.Equal(2, page.TotalPages);
        context.Dispose();
    }

    [Fact]
    public void Create_SecondPage_ReturnsRemainingItems()
    {
        // Arrange
        var context = TestDbContextFactory.CreateWithData();
        var students = context.Students.OrderBy(s => s.LastName);

        // Act
        var page = PaginatedList<Student>.Create(students, 2, 2);

        // Assert
        Assert.Single(page);
        Assert.Equal(2, page.PageIndex);
        context.Dispose();
    }

    [Fact]
    public void HasPreviousPage_FirstPage_ReturnsFalse()
    {
        // Arrange
        var context = TestDbContextFactory.CreateWithData();
        var students = context.Students.OrderBy(s => s.LastName);

        // Act
        var page = PaginatedList<Student>.Create(students, 1, 2);

        // Assert
        Assert.False(page.HasPreviousPage);
        context.Dispose();
    }

    [Fact]
    public void HasPreviousPage_SecondPage_ReturnsTrue()
    {
        // Arrange
        var context = TestDbContextFactory.CreateWithData();
        var students = context.Students.OrderBy(s => s.LastName);

        // Act
        var page = PaginatedList<Student>.Create(students, 2, 2);

        // Assert
        Assert.True(page.HasPreviousPage);
        context.Dispose();
    }

    [Fact]
    public void HasNextPage_FirstPageWithMoreData_ReturnsTrue()
    {
        // Arrange
        var context = TestDbContextFactory.CreateWithData();
        var students = context.Students.OrderBy(s => s.LastName);

        // Act
        var page = PaginatedList<Student>.Create(students, 1, 2);

        // Assert
        Assert.True(page.HasNextPage);
        context.Dispose();
    }

    [Fact]
    public void HasNextPage_LastPage_ReturnsFalse()
    {
        // Arrange
        var context = TestDbContextFactory.CreateWithData();
        var students = context.Students.OrderBy(s => s.LastName);

        // Act
        var page = PaginatedList<Student>.Create(students, 2, 2);

        // Assert
        Assert.False(page.HasNextPage);
        context.Dispose();
    }

    [Fact]
    public void TotalPages_CalculatedCorrectly()
    {
        // Arrange
        var context = TestDbContextFactory.CreateWithData();
        var students = context.Students.OrderBy(s => s.LastName);

        // Act
        var page = PaginatedList<Student>.Create(students, 1, 2);

        // Assert - 3 items / page size 2 = 2 pages
        Assert.Equal(2, page.TotalPages);
        context.Dispose();
    }

    [Fact]
    public void Constructor_SetsProperties()
    {
        // Arrange
        var items = new List<string> { "a", "b", "c" };

        // Act
        var paginatedList = new PaginatedList<string>(items, 10, 2, 3);

        // Assert
        Assert.Equal(3, paginatedList.Count);
        Assert.Equal(2, paginatedList.PageIndex);
        Assert.Equal(4, paginatedList.TotalPages); // ceil(10/3) = 4
    }
}

