using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Data;

public class SchoolContextTests
{
    [Fact]
    public void SchoolContext_CanBeCreatedWithInMemoryDb()
    {
        // Arrange & Act
        using var context = TestDbContextFactory.Create();

        // Assert
        Assert.NotNull(context);
        Assert.NotNull(context.Students);
        Assert.NotNull(context.Courses);
        Assert.NotNull(context.Departments);
        Assert.NotNull(context.Instructors);
        Assert.NotNull(context.Enrollments);
        Assert.NotNull(context.CourseAssignments);
        Assert.NotNull(context.OfficeAssignments);
        Assert.NotNull(context.Notifications);
    }

    [Fact]
    public void SchoolContext_CanAddAndRetrieveStudent()
    {
        // Arrange
        using var context = TestDbContextFactory.Create();
        var student = new Student
        {
            LastName = "TestLast",
            FirstMidName = "TestFirst",
            EnrollmentDate = new DateTime(2023, 9, 1)
        };

        // Act
        context.Students.Add(student);
        context.SaveChanges();

        // Assert
        var retrieved = context.Students.FirstOrDefault(s => s.LastName == "TestLast");
        Assert.NotNull(retrieved);
        Assert.Equal("TestFirst", retrieved.FirstMidName);
        Assert.Equal(new DateTime(2023, 9, 1), retrieved.EnrollmentDate);
    }

    [Fact]
    public void SchoolContext_CanAddAndRetrieveCourse()
    {
        // Arrange
        using var context = TestDbContextFactory.Create();
        context.Departments.Add(new Department
        {
            DepartmentID = 1,
            Name = "Test Dept",
            Budget = 100000,
            StartDate = DateTime.Now
        });
        context.SaveChanges();

        var course = new Course
        {
            CourseID = 101,
            Title = "Test Course",
            Credits = 3,
            DepartmentID = 1
        };

        // Act
        context.Courses.Add(course);
        context.SaveChanges();

        // Assert
        var retrieved = context.Courses.Find(101);
        Assert.NotNull(retrieved);
        Assert.Equal("Test Course", retrieved.Title);
        Assert.Equal(3, retrieved.Credits);
    }

    [Fact]
    public void SchoolContext_CanAddAndRetrieveDepartment()
    {
        // Arrange
        using var context = TestDbContextFactory.Create();
        var department = new Department
        {
            DepartmentID = 10,
            Name = "Science",
            Budget = 250000,
            StartDate = new DateTime(2020, 1, 1)
        };

        // Act
        context.Departments.Add(department);
        context.SaveChanges();

        // Assert
        var retrieved = context.Departments.Find(10);
        Assert.NotNull(retrieved);
        Assert.Equal("Science", retrieved.Name);
        Assert.Equal(250000, retrieved.Budget);
    }

    [Fact]
    public void SchoolContext_CanAddInstructorWithOfficeAssignment()
    {
        // Arrange
        using var context = TestDbContextFactory.Create();
        var instructor = new Instructor
        {
            ID = 100,
            LastName = "TestInst",
            FirstMidName = "WithOffice",
            HireDate = new DateTime(2015, 6, 1),
            CourseAssignments = new List<CourseAssignment>(),
            OfficeAssignment = new OfficeAssignment { Location = "Room 305" }
        };

        // Act
        context.Instructors.Add(instructor);
        context.SaveChanges();

        // Assert
        var retrieved = context.Instructors
            .Include(i => i.OfficeAssignment)
            .FirstOrDefault(i => i.ID == 100);
        Assert.NotNull(retrieved);
        Assert.NotNull(retrieved.OfficeAssignment);
        Assert.Equal("Room 305", retrieved.OfficeAssignment.Location);
    }

    [Fact]
    public void SchoolContext_CanAddEnrollmentWithRelationships()
    {
        // Arrange
        using var context = TestDbContextFactory.CreateWithData();

        var enrollment = new Enrollment
        {
            CourseID = 1050,
            StudentID = 10,
            Grade = Grade.B
        };

        // Act
        context.Enrollments.Add(enrollment);
        context.SaveChanges();

        // Assert
        var retrieved = context.Enrollments
            .Include(e => e.Course)
            .Include(e => e.Student)
            .FirstOrDefault(e => e.CourseID == 1050 && e.StudentID == 10 && e.Grade == Grade.B);
        Assert.NotNull(retrieved);
        Assert.Equal("Chemistry", retrieved.Course.Title);
        Assert.Equal("Alexander", retrieved.Student.LastName);
    }

    [Fact]
    public void SchoolContext_CourseAssignment_CompositeKey_Works()
    {
        // Arrange
        using var context = TestDbContextFactory.CreateWithData();

        // Act - the seeded data has a CourseAssignment with CourseID=1050, InstructorID=1
        var ca = context.CourseAssignments.Find(1050, 1);

        // Assert
        Assert.NotNull(ca);
        Assert.Equal(1050, ca.CourseID);
        Assert.Equal(1, ca.InstructorID);
    }

    [Fact]
    public void SchoolContext_DeleteStudent_RemovesFromDatabase()
    {
        // Arrange
        using var context = TestDbContextFactory.CreateWithData();
        var student = context.Students.Find(10);
        Assert.NotNull(student);

        // Act
        context.Students.Remove(student);
        context.SaveChanges();

        // Assert
        Assert.Null(context.Students.Find(10));
    }

    [Fact]
    public void SchoolContext_UpdateCourse_PersistsChanges()
    {
        // Arrange
        using var context = TestDbContextFactory.CreateWithData();
        var course = context.Courses.Find(1050)!;

        // Act
        course.Title = "Advanced Chemistry";
        context.SaveChanges();

        // Assert
        var updated = context.Courses.Find(1050);
        Assert.Equal("Advanced Chemistry", updated!.Title);
    }

    [Fact]
    public void SchoolContext_People_DbSet_ContainsBothStudentsAndInstructors()
    {
        // Arrange
        using var context = TestDbContextFactory.CreateWithData();

        // Act
        var people = context.People.ToList();

        // Assert - 3 students + 2 instructors
        Assert.Equal(5, people.Count);
    }
}

